    24  struct vcardproperty_impl {
    25      char id[5];
    26      vcardproperty_kind kind;
    27      char *x_name;
    28      char *group;
    29      icalpvl_list parameters;
    30      icalpvl_elem parameter_iterator;
    31      vcardvalue *value;
    32      vcardcomponent *parent;
    33  };
