    35  LIBICAL_VCARD_EXPORT struct vcardproperty_impl *vcardproperty_new_impl(vcardproperty_kind kind)
    36  {
    37      vcardproperty *prop;
    38
    39      if (!vcardproperty_kind_is_valid(kind)) {
    40          return NULL;
    41      }
    42
    43      if ((prop = (vcardproperty *)icalmemory_new_buffer(sizeof(vcardproperty))) == 0) {
    44          icalerror_set_errno(ICAL_NEWFAILED_ERROR);
    45          return 0;
    46      }
    47
    48      memset(prop, 0, sizeof(vcardproperty));
    49
    50      strcpy(prop->id, "prop");
    51
    52      prop->kind = kind;
    53      prop->parameters = icalpvl_newlist();
    54
    55      return prop;
    56  }
