    58  void vcardproperty_add_parameters(vcardproperty *prop, va_list args)
    59  {
    60      void *vp;
    61
    62      while ((vp = va_arg(args, void *)) != 0) {
    63          if (vcardvalue_isa_value(vp) != 0) {
    64          } else if (vcardparameter_isa_parameter(vp) != 0) {
    65              vcardproperty_add_parameter((vcardproperty *)prop,
    66                                          (vcardparameter *)vp);
    67          } else {
    68              icalerror_set_errno(ICAL_BADARG_ERROR);
    69          }
    70      }
    71  }
