    73  vcardproperty *vcardproperty_new(vcardproperty_kind kind)
    74  {
    75      if (kind == VCARD_NO_PROPERTY) {
    76          return 0;
    77      }
    78
    79      return (vcardproperty *)vcardproperty_new_impl(kind);
    80  }
