    82  vcardproperty *vcardproperty_clone(const vcardproperty *old)
    83  {
    84      vcardproperty *clone;
    85      icalpvl_elem p;
    86
    87      icalerror_check_arg_rz((old != 0), "old");
    88      clone = vcardproperty_new_impl(old->kind);
    89      icalerror_check_arg_rz((clone != 0), "clone");
    90
    91      if (old->value != 0) {
    92          clone->value = vcardvalue_clone(old->value);
    93      }
    94
    95      if (old->x_name != 0) {
    96          clone->x_name = icalmemory_strdup(old->x_name);
    97
    98          if (clone->x_name == 0) {
    99              vcardproperty_free(clone);
   100              icalerror_set_errno(ICAL_NEWFAILED_ERROR);
   101              return 0;
   102          }
   103      }
   104
   105      for (p = icalpvl_head(old->parameters); p != 0; p = icalpvl_next(p)) {
   106          vcardparameter *param = vcardparameter_clone(icalpvl_data(p));
   107
   108          if (param == 0) {
   109              vcardproperty_free(clone);
   110              icalerror_set_errno(ICAL_NEWFAILED_ERROR);
   111              return 0;
   112          }
   113
   114          icalpvl_push(clone->parameters, param);
   115      }
   116
   117      return clone;
   118  }
