   120  vcardproperty *vcardproperty_new_from_string(const char *str)
   121  {
   122      size_t buf_size = 1024;
   123      char *buf;
   124      char *buf_ptr;
   125      vcardproperty *prop;
   126      vcardcomponent *comp;
   127      int errors = 0;
   128
   129      icalerror_check_arg_rz((str != 0), "str");
   130
   131      buf = icalmemory_new_buffer(buf_size);
   132      buf_ptr = buf;
   133
   134      /* Is this a HACK or a crafty reuse of code? */
   135
   136      icalmemory_append_string(&buf, &buf_ptr, &buf_size, "BEGIN:VCARD\r\n");
   137      icalmemory_append_string(&buf, &buf_ptr, &buf_size, str);
   138      icalmemory_append_string(&buf, &buf_ptr, &buf_size, "\r\n");
   139      icalmemory_append_string(&buf, &buf_ptr, &buf_size, "END:VCARD\r\n");
   140
   141      comp = vcardparser_parse_string(buf);
   142
   143      if (comp == 0) {
   144          icalerror_set_errno(ICAL_PARSE_ERROR);
   145          icalmemory_free_buffer(buf);
   146          return 0;
   147      }
   148
   149      errors = vcardcomponent_count_errors(comp);
   150
   151      prop = vcardcomponent_get_first_property(comp, VCARD_ANY_PROPERTY);
   152
   153      vcardcomponent_remove_property(comp, prop);
   154
   155      vcardcomponent_free(comp);
   156      icalmemory_free_buffer(buf);
   157
   158      if (errors > 0) {
   159          vcardproperty_free(prop);
   160          return 0;
   161      } else {
   162          return prop;
   163      }
   164  }
