   166  void vcardproperty_free(vcardproperty *p)
   167  {
   168      vcardparameter *param;
   169
   170      icalerror_check_arg_rv((p != 0), "prop");
   171
   172      if (p->parent != 0) {
   173          return;
   174      }
   175
   176      if (p->value != 0) {
   177          vcardvalue_set_parent(p->value, 0);
   178          vcardvalue_free(p->value);
   179      }
   180
   181      while ((param = icalpvl_pop(p->parameters)) != 0) {
   182          vcardparameter_free(param);
   183      }
   184
   185      icalpvl_free(p->parameters);
   186
   187      if (p->x_name != 0) {
   188          icalmemory_free_buffer(p->x_name);
   189      }
   190
   191      if (p->group != 0) {
   192          icalmemory_free_buffer(p->group);
   193      }
   194
   195      p->kind = VCARD_NO_PROPERTY;
   196      p->parameters = 0;
   197      p->parameter_iterator = 0;
   198      p->value = 0;
   199      p->x_name = 0;
   200      p->id[0] = 'X';
   201
   202      icalmemory_free_buffer(p);
   203  }
